CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY AUTOINCREMENT, slug VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, category VARCHAR(100) NOT NULL, daily_rate DECIMAL(10,2) NOT NULL, weekly_rate DECIMAL(10,2) NOT NULL, monthly_rate DECIMAL(10,2) NOT NULL, horsepower INTEGER DEFAULT 300, seating INTEGER DEFAULT 5, powertrain VARCHAR(100) DEFAULT 'Gasoline', transmission VARCHAR(100) DEFAULT '10-Speed Automatic', is_electric INTEGER DEFAULT 0, status VARCHAR(50) DEFAULT 'available', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
